mapper.select:
SELECT , l.changes
FROM sys_operation_log l LEFT JOIN sys_user u ON u.id = l.actor_id


        AND (u.username LIKE #{q.userPattern} ESCAPE '!' OR u.nickname LIKE #{q.userPattern} ESCAPE '!'
        OR l.actor_id = #{q.actorId})

    AND l.action = #{q.action}
    AND l.target_type = #{q.module}
    AND l.result = #{q.result}
    AND l.trace_id = #{q.traceId}
    AND l.created_at >= #{q.startTime}
    AND l.created_at <= #{q.endTime}

ORDER BY l.created_at DESC, l.id DESC

SELECT , l.source_ip, l.changes
FROM sys_operation_log l LEFT JOIN sys_user u ON u.id = l.actor_id
WHERE l.id = #{id}

SELECT l.target_id, l.actor_id, l.changes FROM sys_ip_block b JOIN sys_operation_log l ON l.id = ( SELECT latest.id FROM sys_operation_log latest WHERE latest.target_type = 'IP_BLOCK' AND latest.target_id = b.id AND latest.action = 'IP_BLOCK_RELEASE' AND latest.result = 'SUCCESS' ORDER BY latest.created_at DESC, latest.id DESC LIMIT 1 ) WHERE
b.id IN #{id}
1=0
